/** Actual RN @2x flat-art strips, native palette shader and independently moving foreground. */
internal class TrailParallaxTrackerArt(context:Context){
 private val assets=context.assets;private val images=HashMap<String,Bitmap>();private val shaders=HashMap<String,BitmapShader>();private val faces=HashMap<String,Typeface>()
 private val fill=Paint(Paint.ANTI_ALIAS_FLAG);private val line=Paint(Paint.ANTI_ALIAS_FLAG).apply{style=Paint.Style.STROKE;strokeCap=Paint.Cap.ROUND;strokeJoin=Paint.Join.ROUND};private val text=TextPaint(Paint.ANTI_ALIAS_FLAG).apply{isSubpixelText=true;isLinearText=true}
 private val bitmapPaint=Paint(Paint.ANTI_ALIAS_FLAG).apply{isFilterBitmap=true};private val path=Path();private val rect=RectF()
 private val layers=Array(3){if(Build.VERSION.SDK_INT>=33)RuntimeShader(TrailParallaxTrackerShaders.LAYER)else null}
 private val grain=if(Build.VERSION.SDK_INT>=33)RuntimeShader(TrailParallaxTrackerShaders.GRAIN)else null
 private val bindings=Array(3){""}
 private val strips=arrayOf(arrayOf("b1-canyon-far-ridge-2x","b1-canyon-mid-snow-2x","b1-canyon-near-rim-2x"),arrayOf("b2-granite-far-range-2x","b2-granite-main-spires-2x","b2-granite-near-buttress-2x"),arrayOf("b3-grove-backlight-2x","b3-grove-mid-trunks-2x","b3-grove-near-trunks-2x"),arrayOf("b4-dusk-far-mountain-2x","b4-dusk-mid-hills-2x","b4-dusk-pine-row-2x"))
 private fun image(name:String)=images.getOrPut(name){assets.open("trailparallaxtracker/trailparallaxtracker_${name.replace('-','_')}.png").use{BitmapFactory.decodeStream(it)!!}}
 private fun shader(name:String)=shaders.getOrPut(name){BitmapShader(image(name),Shader.TileMode.CLAMP,Shader.TileMode.CLAMP)}
 private fun font(face:String,size:Float){text.typeface=faces.getOrPut(face){Typeface.createFromAsset(assets,"trailparallaxtracker/trailparallaxtracker_${face.replace('-','_')}.ttf")};text.textSize=size}
 private fun rgb(h:Int,a:Double=1.0)=(h and 0xFFFFFF)or((a.coerceIn(0.0,1.0)*255).roundToInt() shl 24)
 private fun tone(c:DoubleArray,a:Double=1.0)=Color.argb((a*255).roundToInt().coerceIn(0,255),(c[0]*255).roundToInt().coerceIn(0,255),(c[1]*255).roundToInt().coerceIn(0,255),(c[2]*255).roundToInt().coerceIn(0,255))
 private fun polygon(points:Array<DoubleArray>):Path{val p=Path();p.moveTo(points[0][0].toFloat(),points[0][1].toFloat());for(q in points.drop(1))p.lineTo(q[0].toFloat(),q[1].toFloat());p.close();return p}
 private fun paint(c:Canvas,p:Path,color:Int){fill.color=rgb(color);c.drawPath(p,fill)}
 private fun label(c:Canvas,value:String,x:Double,base:Double,face:String,size:Double,color:Int,center:Boolean=false){font(face,size.toFloat());text.color=color;text.textAlign=if(center)Paint.Align.CENTER else Paint.Align.LEFT;c.drawText(value,x.toFloat(),base.toFloat(),text)}
 fun draw(c:Canvas,f:TrailParallaxTrackerFrame,h:Double,reduced:Boolean,renderScale:Double){
  val m=TrailParallaxTrackerMath;val dy=h-874;val scene=530+dy;val base=500+dy;val camera=f.d*24;val sp=TrailParallaxTrackerWorld.split(camera,reduced);val row=TrailParallaxTrackerLight.hour(f.d);val pa=TrailParallaxTrackerLight.palette(sp.a,row);val pb=TrailParallaxTrackerLight.palette(sp.b,row)
  fill.color=Color.WHITE;c.drawColor(rgb(0x060606));c.save();c.clipRect(0f,0f,402f,(scene+40).toFloat())
  for(side in 0 until if(sp.a==sp.b)1 else 2){val p=if(side==0)pa else pb;val x=if(side==0)0.0 else sp.x.coerceIn(0.0,402.0);val right=if(side==0)sp.x.coerceIn(0.0,402.0)else 402.0;fill.shader=LinearGradient(0f,0f,0f,(490+dy).toFloat(),intArrayOf(tone(p.sky[0]),tone(p.sky[1]),tone(p.sky[2])),floatArrayOf(0f,.6f,1f),Shader.TileMode.CLAMP);c.drawRect(x.toFloat(),0f,right.toFloat(),(scene+40).toFloat(),fill);fill.shader=null}
  for(depth in 0..2){
   val effect=layers[depth]
   if(Build.VERSION.SDK_INT>=33&&effect!=null){
    val key="${sp.a}/${sp.b}";if(bindings[depth]!=key){effect.setInputShader("imgA",shader(strips[sp.a][depth]));effect.setInputShader("imgB",shader(strips[sp.b][depth]));bindings[depth]=key}
    effect.setFloatUniform("uSplit",sp.x.toFloat());effect.setFloatUniform("uTop",(dy+90).toFloat());effect.setFloatUniform("uScA",2f);effect.setFloatUniform("uScB",2f)
    effect.setFloatUniform("uOffA",TrailParallaxTrackerWorld.offset(sp.a,depth,camera,reduced).toFloat());effect.setFloatUniform("uOffB",TrailParallaxTrackerWorld.offset(sp.b,depth,camera,reduced).toFloat())
    effect.setFloatUniform("uNA",pa.count.toFloat());effect.setFloatUniform("uNB",pb.count.toFloat());effect.setFloatUniform("uSrcA",pa.source);effect.setFloatUniform("uDstA",pa.destination);effect.setFloatUniform("uSrcB",pb.source);effect.setFloatUniform("uDstB",pb.destination);effect.setFloatUniform("uBlur",if(depth==0||reduced)0f else min(14.0,abs(f.v)*.22).toFloat())
    fill.color=Color.WHITE;fill.shader=effect;c.drawRect(0f,0f,402f,(scene+40).toFloat(),fill);fill.shader=null
   }else{for(side in 0 until if(sp.a==sp.b)1 else 2){val bi=if(side==0)sp.a else sp.b;val p=if(side==0)pa else pb;val off=TrailParallaxTrackerWorld.offset(bi,depth,camera,reduced);val b=TrailParallaxTrackerWorld.biomes[bi];c.save();c.clipRect(if(side==0)0f else sp.x.toFloat(),0f,if(side==0)sp.x.toFloat()else 402f,(scene+40).toFloat());val img=image(strips[bi][depth]);bitmapPaint.colorFilter=ColorMatrixColorFilter(ColorMatrix(floatArrayOf(1f,0f,0f,0f,(p.destination[0]-p.source[0])*255,0f,1f,0f,0f,(p.destination[1]-p.source[1])*255,0f,0f,1f,0f,(p.destination[2]-p.source[2])*255,0f,0f,0f,1f,0f)));rect.set((-off).toFloat(),(dy+90).toFloat(),(b.width-off).toFloat(),(dy+530).toFloat());c.drawBitmap(img,null,rect,bitmapPaint);bitmapPaint.colorFilter=null;c.restore()}}
   if(depth==1)drawShafts(c,camera,sp,scene,reduced)
  };c.restore()
  val rim=Path();for((i,x)in (-12..414 step 6).withIndex()){val y=m.ground(x+camera,base);if(i==0)rim.moveTo(x.toFloat(),y.toFloat())else rim.lineTo(x.toFloat(),y.toFloat())}
  val ground=Path(rim);ground.lineTo(414f,(h+10).toFloat());ground.lineTo(-12f,(h+10).toFloat());ground.close();fill.color=rgb(0x060606);c.drawPath(ground,fill)
  for(side in 0 until if(sp.a==sp.b)1 else 2){val p=if(side==0)pa else pb;val x=if(side==0)-20.0 else max(-20.0,min(sp.x,460.0));val right=if(side==0)min(sp.x,460.0)else 460.0;c.save();c.clipRect(x.toFloat(),0f,right.toFloat(),h.toFloat());c.save();c.clipPath(ground);line.color=tone(p.sky[2],.24);line.strokeWidth=28f;line.setShadowLayer(5f,0f,0f,tone(p.sky[2],.24));c.drawPath(rim,line);line.clearShadowLayer();c.restore();line.color=tone(p.sky[2],.75);line.strokeWidth=2.5f;c.drawPath(rim,line);c.restore()}
  val foot=m.ground(200+camera,base)+1;val slope=atan2(m.ground(206+camera,base)-m.ground(194+camera,base),12.0);val angle=(slope*180/PI*.6+f.lean*f.face).coerceIn(-14.0,14.0)
  fill.color=rgb(0,.35);c.drawOval(186f,(foot-2).toFloat(),214f,(foot+2).toFloat(),fill)
  c.save();c.translate(200f,(foot-4*f.hop).toFloat());c.rotate(angle.toFloat());c.scale(f.face.toFloat(),f.squash.toFloat());val w=93*204/288.0;rect.set((-105.0/204*w).toFloat(),(-280.0/288*93).toFloat(),(-105.0/204*w+w).toFloat(),(-280.0/288*93+93).toFloat());val pose=f.pose.toInt().coerceIn(0,18);c.drawBitmap(image("hiker-sheet"),Rect(pose*204,0,(pose+1)*204,288),rect,bitmapPaint);c.restore()
  if(f.skidAge>=0&&f.skidAge<.32){val k=f.skidAge/.32;for((i,r)in doubleArrayOf(5.0,8.0,6.0).withIndex()){val radius=r*sin(PI*min(1.0,k*1.15+i*.05));fill.color=tone(pa.sky[2],.6);c.drawCircle((200-f.face*(8+i*9)).toFloat(),(foot-3-10*k-i*2).toFloat(),radius.toFloat(),fill)}}
  val occ=Path();occ.moveTo(-12f,-20f);for(x in -12..414 step 6)occ.lineTo(x.toFloat(),(m.ground(x+camera,base)+30).toFloat());occ.lineTo(414f,-20f);occ.close();c.save();c.clipPath(occ)
  val rate=if(reduced)1.0 else 1.7;val fin=201-150-rate*(camera-624);val trunk=201-165-rate*(camera-1408.8);val grove=201-123.75-rate*(camera-1759);val wall=201-340/3.0*1.6-rate*(camera-2900);val pines=201-564/3.0*1.3-rate*(camera-3350)
  if(fin<420&&fin+300> -80){c.save();c.translate(fin.toFloat(),(dy+90).toFloat());drawRock(c);c.restore()}
  if(grove<420&&grove+247.5> -80){c.save();c.translate(grove.toFloat(),(dy+90).toFloat());c.scale(.75f,1f);drawTrunk(c,true);c.restore()}
  if(wall<420&&wall+623.3> -80){drawBitmap(c,"occluder-black-trunk",wall,scene+26-440*1.6,700/3.0*1.6,440*1.6);drawBitmap(c,"occluder-black-pine-cluster",wall+700/3.0*1.6-180,scene+26-440*1.3,1000/3.0*1.3,440*1.3)}
  if(pines<420&&pines+433.3> -80)drawBitmap(c,"occluder-black-pine-cluster",pines,scene+26-440*1.3,1000/3.0*1.3,440*1.3)
  if(trunk<420&&trunk+330> -80){c.save();c.translate(trunk.toFloat(),(dy+90).toFloat());drawTrunk(c,false);c.restore()};c.restore()
  if(Build.VERSION.SDK_INT>=33&&grain!=null){grain.setFloatUniform("uScale",renderScale.toFloat());fill.color=Color.WHITE;fill.shader=grain;c.drawRect(0f,0f,402f,scene.toFloat(),fill);fill.shader=null}
  drawOdometers(c,f,dy,reduced)
  val bs=max(f.bubS,0.0);if(bs>.01){val float=1.5*sin(2*PI*3*f.time/12);val hy=foot-109+float;val x=m.mix(200.0,200-f.face*14,f.bubT);val y=m.mix(hy,foot-45,f.bubT);c.save();c.translate(x.toFloat(),(y-25).toFloat());c.scale(bs.toFloat(),bs.toFloat());fill.color=Color.WHITE;c.drawRoundRect(RectF(-42f,-25f,42f,25f),12f,12f,fill);label(c,"Today",0.0,-6.0,"Inter-SemiBold",13.0,rgb(0x6B6B6B),true);label(c,"0.6 mi",0.0,14.0,"Outfit-Bold",17.0,rgb(0x0A0A0A),true);c.restore()}
  drawCard(c,f,dy,reduced);for(i in 0..2){c.save();c.translate(floatArrayOf(65f,189f,313f)[i],(801+dy).toFloat());drawIcon(c,i);c.restore()}
 }
 private fun drawBitmap(c:Canvas,name:String,x:Double,y:Double,w:Double,h:Double){rect.set(x.toFloat(),y.toFloat(),(x+w).toFloat(),(y+h).toFloat());c.drawBitmap(image(name),null,rect,bitmapPaint)}
 private fun drawShafts(c:Canvas,camera:Double,sp:TrailParallaxTrackerWorld.Split,scene:Double,reduced:Boolean){c.save();when{sp.a==2&&sp.b==2->c.clipRect(-50f,0f,470f,scene.toFloat());sp.b==2->c.clipRect(sp.x.toFloat(),0f,(sp.x+600).toFloat(),scene.toFloat());sp.a==2->c.clipRect(-200f,0f,sp.x.toFloat(),scene.toFloat());else->{c.restore();return}};val rel=camera-1408.8;fill.color=rgb(0xF8FAD6,.45);for(pair in arrayOf(doubleArrayOf(284.0,56.0),doubleArrayOf(372.0,42.0),doubleArrayOf(446.0,68.0),doubleArrayOf(640.0,50.0),doubleArrayOf(800.0,64.0),doubleArrayOf(1010.0,44.0))){val x=pair[0]-rel*(if(reduced)1.0 else .5);val w=pair[1];if(x>460||x< -260)continue;c.drawPath(polygon(arrayOf(doubleArrayOf(x,-4.0),doubleArrayOf(x+w*.62,-4.0),doubleArrayOf(x+w*.62+150,scene),doubleArrayOf(x+150-w*.38,scene))),fill)};c.restore()}
 private fun drawRock(c:Canvas){val left=arrayOf(doubleArrayOf(-46.0,620.0),doubleArrayOf(-34.0,430.0),doubleArrayOf(-6.0,372.0),doubleArrayOf(0.0,330.0),doubleArrayOf(22.0,300.0),doubleArrayOf(30.0,240.0),doubleArrayOf(58.0,205.0),doubleArrayOf(64.0,140.0),doubleArrayOf(88.0,90.0),doubleArrayOf(96.0,30.0),doubleArrayOf(110.0,-200.0));val right=arrayOf(doubleArrayOf(205.0,-200.0),doubleArrayOf(214.0,40.0),doubleArrayOf(240.0,70.0),doubleArrayOf(248.0,150.0),doubleArrayOf(276.0,190.0),doubleArrayOf(284.0,270.0),doubleArrayOf(300.0,320.0),doubleArrayOf(324.0,400.0),doubleArrayOf(342.0,470.0),doubleArrayOf(350.0,620.0));val r1=arrayOf(doubleArrayOf(118.0,60.0),doubleArrayOf(104.0,160.0),doubleArrayOf(120.0,260.0),doubleArrayOf(98.0,360.0),doubleArrayOf(112.0,620.0));val r2=arrayOf(doubleArrayOf(205.0,-200.0),doubleArrayOf(190.0,80.0),doubleArrayOf(202.0,190.0),doubleArrayOf(184.0,300.0),doubleArrayOf(198.0,420.0),doubleArrayOf(190.0,620.0));paint(c,polygon(left+right),0x4B5980);paint(c,polygon(left+r1),0x6E6C96);paint(c,polygon(right+r2.reversed().dropLast(1).toTypedArray()),0x323C5A);paint(c,polygon(arrayOf(doubleArrayOf(150.0,40.0),doubleArrayOf(156.0,120.0),doubleArrayOf(146.0,210.0),doubleArrayOf(152.0,232.0),doubleArrayOf(162.0,120.0),doubleArrayOf(157.0,40.0))),0x323C5A);paint(c,polygon(arrayOf(doubleArrayOf(118.0,60.0),doubleArrayOf(138.0,92.0),doubleArrayOf(112.0,118.0))),0x9A8AA5)}
 private fun drawTrunk(c:Canvas,grove:Boolean){val lit=if(grove)0x2C4F45 else 0xA8392B;val body=if(grove)0x0D1418 else 0x8E2A22;val shade=if(grove)0x080C0E else 0x5E1A1C
  fun band(a:(Double)->Double,b:(Double)->Double):Path{val ys=(-200..620 step 20).map{it.toDouble()};return polygon((ys.map{doubleArrayOf(a(it),it)}+ys.reversed().map{doubleArrayOf(b(it),it)}).toTypedArray())}
  val edgeL:(Double)->Double={8-8*((it+200)/820)+2.5*sin(it/37)};val edgeR:(Double)->Double={320+10*((it+200)/820)+2*sin(it/29+1)};val litEdge:(Double)->Double={72.6+5*sin(it/23)+3*sin(it/9)};val shadeEdge:(Double)->Double={231+4*sin(it/31+2)+2*sin(it/11)};val fissL:(Double)->Double={155.1+7*sin(it/41)-3}
  paint(c,polygon(arrayOf(doubleArrayOf(10.0,118.0),doubleArrayOf(-58.0,76.0),doubleArrayOf(-62.0,86.0),doubleArrayOf(8.0,150.0))),body);paint(c,polygon(arrayOf(doubleArrayOf(10.0,118.0),doubleArrayOf(-58.0,76.0),doubleArrayOf(-62.0,86.0),doubleArrayOf(4.0,126.0))),lit);paint(c,polygon(arrayOf(doubleArrayOf(320.0,236.0),doubleArrayOf(384.0,196.0),doubleArrayOf(390.0,206.0),doubleArrayOf(380.0,214.0),doubleArrayOf(324.0,270.0))),if(grove)0x070B0D else 0x4A1517)
  paint(c,band(edgeL,litEdge),lit);paint(c,band(litEdge,shadeEdge),body);paint(c,band(shadeEdge,edgeR),shade);paint(c,band(fissL,{fissL(it)+5+3*abs(sin(it/17))}),shade)
  for((i,n)in arrayOf(doubleArrayOf(30.0,60.0,16.0,30.0),doubleArrayOf(110.0,190.0,22.0,42.0),doubleArrayOf(190.0,300.0,18.0,34.0),doubleArrayOf(262.0,110.0,20.0,38.0)).withIndex()){val x=n[0];val y=n[1];val w=n[2];val h=n[3];paint(c,polygon(arrayOf(doubleArrayOf(x,y),doubleArrayOf(x+w/2,y+h*.35),doubleArrayOf(x+w,y),doubleArrayOf(x+w*.62,y+h),doubleArrayOf(x+w*.38,y+h))),if(grove){if(i==0)0x1B332D else shade}else if(i==3)0x47131A else shade)}
 }
 private fun drawOdometers(c:Canvas,f:TrailParallaxTrackerFrame,dy:Double,reduced:Boolean){font("Outfit-Bold",76f);val widths=(0..9).map{text.measureText(it.toString()).toDouble()};val cell=widths.max()+1.2;val dot=text.measureText(".")+1.2;val total=4*cell+dot;val x0=201-total/2;val base=630+dy;val m=(825.7-f.d.coerceIn(0.0,150.0))*10;val xs=doubleArrayOf(x0+3*cell+dot,x0+2*cell,x0+cell,x0)
  for(j in 0..3)drum(c,m,j,xs[j],cell,base,84.0,"Outfit-Bold",76.0,rgb(0xFCFCFA),560+dy,648+dy,if(reduced)0.0 else f.v);label(c,".",x0+3*cell+.6,base,"Outfit-Bold",76.0,rgb(0xFCFCFA))
  font("Inter-Medium",17f);val dayCell=(0..9).maxOf{text.measureText(it.toString()).toDouble()};val labelWidth=text.measureText("Day ").toDouble();val dayX=201-(labelWidth+3*dayCell)/2;val dayBase=562+dy;val day=TrailParallaxTrackerMath.day(f.d.coerceIn(0.0,150.0));label(c,"Day ",dayX,dayBase,"Inter-Medium",17.0,rgb(0x8C8C8C));for(j in 0..2)drum(c,day,2-j,dayX+labelWidth+j*dayCell,dayCell,dayBase,22.0,"Inter-Medium",17.0,rgb(0x8C8C8C),dayBase-19,dayBase+6,0.0);label(c,"miles",201.0,661+dy,"Inter-Medium",17.0,rgb(0x8C8C8C),true)
 }
 private fun drum(c:Canvas,value:Double,column:Int,x:Double,cell:Double,base:Double,step:Double,face:String,size:Double,color:Int,top:Double,bottom:Double,speed:Double){
  val p=TrailParallaxTrackerMath.odo(value,column);val k=((abs(speed)*10/10.0.pow(column)-4)/40).coerceIn(0.0,1.0);val travel=step*(1-.2*k);val fade=min(16.0,(bottom-top)*.2)
  c.save();c.clipRect((x-4).toFloat(),top.toFloat(),(x+cell+4).toFloat(),bottom.toFloat());val checkpoint=c.saveLayer(RectF((x-4).toFloat(),top.toFloat(),(x+cell+4).toFloat(),bottom.toFloat()),null)
  font(face,size.toFloat());for(i in -1..2){val d=((floor(p).toInt()+i)%10+10)%10;val y=base+(i-(p-floor(p)))*travel;val width=text.measureText(d.toString());label(c,d.toString(),x+(cell-width)/2,y,face,size,color)}
  fill.shader=LinearGradient(0f,top.toFloat(),0f,bottom.toFloat(),intArrayOf(0x00000000,Color.BLACK,Color.BLACK,0x00000000),floatArrayOf(0f,(fade/(bottom-top)).toFloat(),(1-fade/(bottom-top)).toFloat(),1f),Shader.TileMode.CLAMP);fill.xfermode=PorterDuffXfermode(PorterDuff.Mode.DST_IN);fill.alpha=255;c.drawRect((x-4).toFloat(),top.toFloat(),(x+cell+4).toFloat(),bottom.toFloat(),fill);fill.shader=null;fill.xfermode=null;c.restoreToCount(checkpoint);c.restore()
 }

 private fun drawCard(c:Canvas,f:TrailParallaxTrackerFrame,dy:Double,reduced:Boolean){val y=676+dy;val w=374.0;val h=95.0;val p=if(reduced)(f.cardAge/.2).coerceIn(0.0,1.0)else TrailParallaxTrackerMath.cardProgress(f.cardAge);val forward=f.cardDir>=0;val edge=if(forward)w*(1-p)else w*p;c.save();c.translate(14f,y.toFloat());path.rewind();path.addRoundRect(RectF(0f,0f,374f,95f),14f,14f,Path.Direction.CW);c.clipPath(path);fill.color=rgb(0x111610);c.drawRect(0f,0f,374f,95f,fill)
  for(isNew in booleanArrayOf(false,true)){val index=(if(isNew)f.cardTo else f.cardFrom).toInt().coerceIn(0,7);val l=if(isNew){if(forward)edge else 0.0}else if(forward)0.0 else edge;val width=if(isNew){if(forward)w-edge else edge}else if(forward)edge else w-edge;val slide=if(reduced)0.0 else if(isNew)(if(forward)24 else -24)*(1-p)else (if(forward)-24 else 24)*p;if(width<=0)continue;c.save();c.clipRect((if(reduced)0.0 else l).toFloat(),0f,(if(reduced)w else l+width).toFloat(),h.toFloat());val alpha=if(reduced){if(isNew)p else 1-p}else 1.0;c.translate(slide.toFloat(),0f);val wp=TrailParallaxTrackerWorld.waypoints[index];line.color=rgb(0xFFFFFF,alpha);line.strokeWidth=1.5f;c.drawCircle(22f,21f,4f,line);c.drawLine(18f,24f,22f,30f,line);c.drawLine(26f,24f,22f,30f,line);label(c,wp.name,38.0,28.0,"Inter-SemiBold",15.0,rgb(0xFFFFFF,alpha));font("Inter-Regular",13f);text.color=rgb(0x8F938C,alpha);text.textAlign=Paint.Align.LEFT
   val layout=StaticLayout.Builder.obtain(wp.note,0,wp.note.length,text,346).setAlignment(Layout.Alignment.ALIGN_NORMAL).setIncludePad(false).setMaxLines(2).setEllipsize(TextUtils.TruncateAt.END).setLineSpacing(19-(text.fontMetrics.descent-text.fontMetrics.ascent),1f).build();c.translate(14f,40f);layout.draw(c);c.restore()}
  if(!reduced&&f.cardFrom!=f.cardTo&&p>0&&p<1){fill.color=rgb(0x111610);c.drawRect((edge-7).toFloat(),0f,(edge+7).toFloat(),95f,fill);fill.color=rgb(0xFFFFFF,.28);c.drawRect((edge-.75).toFloat(),0f,(edge+.75).toFloat(),95f,fill)};c.restore()
 }
 private fun drawIcon(c:Canvas,i:Int){path.rewind();if(i==0){for(x in doubleArrayOf(5.0,12.5)){path.moveTo(x.toFloat(),6.5f);path.lineTo((x+5.5).toFloat(),12f);path.lineTo(x.toFloat(),17.5f)}}else if(i==1){path.addPath(polygon(arrayOf(doubleArrayOf(3.5,6.5),doubleArrayOf(9.0,4.0),doubleArrayOf(15.0,6.5),doubleArrayOf(20.5,4.0),doubleArrayOf(20.5,17.5),doubleArrayOf(15.0,20.0),doubleArrayOf(9.0,17.5),doubleArrayOf(3.5,20.0))));path.moveTo(9f,4f);path.lineTo(9f,17.5f);path.moveTo(15f,6.5f);path.lineTo(15f,20f)}else{path.addPath(polygon(arrayOf(doubleArrayOf(12.0,3.0),doubleArrayOf(19.8,7.5),doubleArrayOf(19.8,16.5),doubleArrayOf(12.0,21.0),doubleArrayOf(4.2,16.5),doubleArrayOf(4.2,7.5))));path.moveTo(8.6f,12.6f);path.lineTo(12f,15f);path.lineTo(15.4f,12.6f)};line.color=rgb(if(i==0)0xFFFFFF else 0xB5B5B5);line.strokeWidth=2f;c.drawPath(path,line)}
}
